<?php
declare(strict_types=1);
// File/authorization tests use an explicit authenticator double; real SMTP remains a host acceptance gate.
require __DIR__.'/../src/Kernel.php';require __DIR__.'/../bin/configure-smtp.php';
$path=getenv('ZENITH_TEST_CONFIG')?:__DIR__.'/../../work/private/config.php';$config=require $path;if(($config['environment']??'')!=='test')throw new RuntimeException('Test configuration required.');$config['session_enabled']=false;$k=new Zenith\Kernel($config);$id=$k->id();$email='smtp-'.$id.'@example.test';$now=$k->now();
$k->execute("INSERT INTO users(id,name,email,password_hash,role,email_verified_at,created_at,updated_at) VALUES(?,?,?,?,'admin',?,?,?)",[$id,'SMTP test operator',$email,password_hash('Test-admin-smtp-456!',PASSWORD_DEFAULT),$now,$now,$now]);
$root=sys_get_temp_dir().'/zenith-smtp-'.bin2hex(random_bytes(8));$release=$root.'/releases/'.str_repeat('c',40);mkdir($release.'/private/backend/src',0700,true);mkdir($release.'/private/shared',0700,true);copy(__DIR__.'/../src/Kernel.php',$release.'/private/backend/src/Kernel.php');copy(__DIR__.'/../../shared/contract.json',$release.'/private/shared/contract.json');file_put_contents($release.'/release-manifest.json',json_encode(['commit'=>str_repeat('c',40),'dirty'=>false,'files'=>['private/backend/src/Kernel.php'=>hash_file('sha256',__DIR__.'/../src/Kernel.php')]]));
$cfg=$root.'/config.php';file_put_contents($cfg,'<?php return '.var_export($config,true).';');chmod($cfg,0600);$before=hash_file('sha256',$cfg);
$driver=$root.'/driver.php';file_put_contents($driver,'<?php require '.var_export(realpath(__DIR__.'/../bin/configure-smtp.php'),true).'; $mail=json_decode(stream_get_contents(STDIN),true,512,JSON_THROW_ON_ERROR); try { ZenithSmtpSetup::save($argv[1],$argv[2],$argv[3],$mail,static function(array $settings)use($argv):void{if($argv[4]==="fail")throw new RuntimeException("TEST SMTP verification rejected (code535).");}); echo "saved"; } catch(Throwable $e){fwrite(STDERR,$e instanceof RuntimeException&&!$e instanceof PDOException?$e->getMessage():"TEST database operation failed");exit(1);}');
$mail=['transport'=>'smtp','host'=>'smtp.example.test','port'=>465,'encryption'=>'ssl','username'=>'sender@example.test','password'=>"Test-mailbox-'quoted-password-2026!",'from'=>'sender@example.test','from_name'=>'A Zenith Fashion'];$checks=0;
function check(bool $v,string $label):void{global $checks;if(!$v)throw new RuntimeException('FAIL '.$label);$checks++;}
function saveMail(string $driver,string $cfg,string $release,string $email,array $mail,string $mode='ok'):array{$pipes=[];$p=proc_open([PHP_BINARY,$driver,$cfg,$release,$email,$mode],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);fwrite($pipes[0],json_encode($mail));fclose($pipes[0]);$out=stream_get_contents($pipes[1]).stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);return [proc_close($p),$out];}
try{
    [$status]=saveMail($driver,$cfg,$release,$email,$mail,'fail');check($status!==0&&hash_equals($before,hash_file('sha256',$cfg)),'Authentication failure leaves config unchanged');
    [$status]=saveMail($driver,$cfg,$release,'missing@example.test',$mail);check($status!==0&&hash_equals($before,hash_file('sha256',$cfg)),'Only existing administrator may configure SMTP');
    $invalid=$mail;$invalid['encryption']='none';[$status]=saveMail($driver,$cfg,$release,$email,$invalid);check($status!==0,'Unencrypted mail rejected');
    $invalid=$mail;$invalid['from']='unrelated@example.test';[$status]=saveMail($driver,$cfg,$release,$email,$invalid);check($status!==0,'Sender must match authenticated mailbox');
    $invalid=$mail;$invalid['host']="smtp.example.test\r\nInjected";[$status]=saveMail($driver,$cfg,$release,$email,$invalid);check($status!==0,'Invalid host rejected');
    [$status,$out]=saveMail($driver,$cfg,$release,$email,$mail);check($status===0,'Verified authenticator result allows private update');check(!str_contains($out,$mail['password']),'Mailbox secret absent from output');
    $updated=require $cfg;check($updated['mail']===$mail,'Quoted mailbox password round-trips');check($updated['db']===$config['db'],'Database settings unchanged');check($updated['manual_payments_enabled']===$config['manual_payments_enabled']&&$updated['merchant']===$config['merchant'],'Commercial approval settings unchanged');check((fileperms($cfg)&0777)===0600,'Updated config permission0600');
    $backups=glob($root.'/backups/config-pre-smtp-*.php');check(count($backups)===1&&hash_equals($before,hash_file('sha256',$backups[0])),'Original config preserved in private backup');check((fileperms($backups[0])&0777)===0600,'Backup permission0600');
    $audit=$k->all("SELECT details FROM audit_events WHERE actor_id=? AND action='mail.configuration_updated'",[$id]);check(count($audit)===1&&!str_contains(json_encode($audit),$mail['password']),'Password-free audit event recorded');
    $s=fopen('php://temp','r+');fwrite($s,"250-First\r\n250 Accepted\r\n");rewind($s);ZenithSmtpSetup::reply($s,[250]);fclose($s);check(true,'SMTP multiline reply accepted');
    $s=fopen('php://temp','r+');fwrite($s,"535 fake-sensitive-provider-text\r\n");rewind($s);try{ZenithSmtpSetup::reply($s,[235]);check(false,'Auth rejection');}catch(RuntimeException $e){check(str_contains($e->getMessage(),'535')&&!str_contains($e->getMessage(),'fake-sensitive-provider-text'),'SMTP rejection exposes numeric code only');}fclose($s);
    check(count(glob($root.'/.smtp-config-*'))===0,'Temporary credential files cleaned');
    echo 'PASS '.$checks." SMTP configuration integrity/protocol assertions; remote TLS/auth not simulated as verified.\n";
}finally{$files=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::CHILD_FIRST);foreach($files as $file){if($file->isFile()||$file->isLink())unlink($file->getPathname());else rmdir($file->getPathname());}rmdir($root);}
